mapper.select:
SELECT COUNT(*)
FROM orders
WHERE checkout_id = #{checkoutId}

mapper.update:
UPDATE orders
SET status = 'PACKED', updated_at = CURRENT_TIMESTAMP
WHERE id = #{orderId}
  AND shop_id = #{shopId}
  AND status IN ('CONFIRMED', 'PREPARING')

mapper.sql:
WHERE o.customer_id = #{customerId}
AND o.status = #{status}

    AND EXISTS (
        SELECT 1 FROM order_items oi_search
        WHERE oi_search.order_id = o.id
          AND oi_search.product_name ILIKE CONCAT('%', #{keyword}, '%')
    )
